// Flatten each lead into a flat row: join array fields into strings so they fit a single Sheet cell, and carry the niche/location through from the parent payload.
const niche = $('Leads Webhook').first().json.body.niche;
const location = $('Leads Webhook').first().json.body.location;

return items.map(item => {
  const l = item.json;
  return {
    json: {
      niche,
      location,
      name: l.name,
      phone: l.phone,
      email: l.email || '',
      website: l.website || '',
      address: l.address,
      category: l.category,
      rating: l.rating,
      review_count: l.review_count,
      lead_score: l.lead_score,
      website_intent_score: l.website_intent_score,
      other_intents: Array.isArray(l.other_intents) ? l.other_intents.join(' | ') : (l.other_intents || ''),
      intent_notes: l.intent_notes,
      running_ads: l.running_ads,
      dm_order_flow: l.dm_order_flow,
      checkout_present: l.checkout_present,
      owner_response_ratio: l.owner_response_ratio,
      cid: l.cid,
      maps_url: l.maps_url,
      scraped_at: new Date().toISOString()
    }
  };
});
